/** @file Tags together, with one blank line before @returns, and a block with @returns alone. */

/**
 * Adds two numbers.
 *
 * @param a The first.
 * @param b The second, which can
 *   run over two lines.
 *
 * @returns Their sum.
 */
export function add(a, b) {
  return a + b;
}

/**
 * The answer.
 *
 * @returns Forty-two.
 */
export function answer() {
  return 42;
}
